 insert into public.prisma_lots(product_id,lot,entry_date,shelf_days,cost_kg,grams) values(pid,'MIX-'||r.id||'-'||d,d,365,total_cost/(output/1000),output) returning id into lid;
 for ingredient in select (v->>'lot_id')::bigint as lot_id,sum(case when v?'grams' then public.prisma_number(v->>'grams','Gramos de tinta') else public.prisma_number(v->>'kilograms','Kilos de tinta')*1000 end) as grams from jsonb_array_elements(payload->'ingredients')v group by (v->>'lot_id')::bigint loop
