  on conflict(code) do update set name=excluded.name,kind=excluded.kind,provider=excluded.provider,cost_kg=excluded.cost_kg,tool_type=excluded.tool_type,tooling_details=excluded.tooling_details returning id into pid;
  if not exists(select 1 from public.prisma_lots where product_id=pid) then
   insert into public.prisma_lots(product_id,lot,entry_date,shelf_days,cost_kg,grams) values(pid,item->>'lot',public.prisma_today(),0,(item->>'cost_kg')::numeric,1) returning id into lid;
   insert into public.prisma_movements(lot_id,type,grams,cost_kg,date,reason) values(lid,'in',1,(item->>'cost_kg')::numeric,public.prisma_today(),'Alta de herramental · Inventario de Hernamentales.pdf · '||(item->>'code'));
  end if;
 end loop;
 insert into public.prisma_metadata values('tooling_pdf_20261104_v1','1');
 end if;
end $tool_import$;
create or replace function public.prisma_order_portal(access_key text,payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
<<portal>>
declare b jsonb:=payload->'order';old public.prisma_order_portal_submissions%rowtype;request_id uuid;signature text;oid bigint;n bigint;planned date;row_data jsonb;more boolean;cursor_value bigint;item jsonb;field text;maxlen integer;selections jsonb;selection jsonb;labels text[];product_row public.prisma_products%rowtype;slots integer[];slot_value integer;die_row public.prisma_products%rowtype;crease_row public.prisma_products%rowtype;
begin
 if access_key is null or access_key !~ '^op_[a-f0-9]{64}$' then raise exception 'Enlace no autorizado.';end if;
 perform pg_advisory_xact_lock(104202611);
 if not exists(select 1 from public.prisma_order_portal_access where id=1 and enabled and token_hash=encode(sha256(convert_to(access_key,'UTF8')),'hex')) then raise exception 'El enlace fue desactivado o cambió. Solicita el enlace vigente.';end if;
 if payload->>'operation'='catalog' then
 return jsonb_build_object('tools',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'code',p.code,'name',p.name,'tool_type',case when p.code like 'SJ%' then 'suaje' else 'pleca' end) order by p.name,p.code) from public.prisma_products p where p.category='herramental' and (p.code like 'SJ%' or p.code like 'PD%')),'[]'::jsonb),'products',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'code',p.code,'name',p.name,'kind',p.kind,'provider',p.provider,'available',exists(select 1 from public.prisma_lots l where l.product_id=p.id and l.grams>0)) order by p.name,p.code) from public.prisma_products p where p.category='tinta'),'[]'::jsonb));
 elsif payload->>'operation'='list' then
  cursor_value:=coalesce((payload->>'after_sequence')::bigint,0);
  select coalesce(jsonb_agg(to_jsonb(x) order by x.queue_number),'[]'::jsonb) into row_data from
   (select id,queue_number,folio,np,product,client,pressman,machine,scheduled_date,scheduled_start,scheduled_end,pieces,planned_meters,specifications->>'colores' as colors,specifications->>'suaje' as die,specifications->>'pleca' as crease,notes,status,started_at,ended_at,received_at
    from public.prisma_orders where source='portal' and queue_number>cursor_value and (coalesce((payload->>'include_finished')::boolean,false) or (status<>'cancelled' and ended_at is null)) order by queue_number limit 50)x;
  select exists(select 1 from public.prisma_orders where source='portal' and queue_number>coalesce((row_data->-1->>'queue_number')::bigint,cursor_value) and (coalesce((payload->>'include_finished')::boolean,false) or (status<>'cancelled' and ended_at is null))) into more;
  return jsonb_build_object('orders',row_data,'has_more',more);
 elsif payload->>'operation' is distinct from 'submit' then raise exception 'Acción no permitida.';end if;
 if b is null or jsonb_typeof(b)<>'object' or octet_length(b::text)>10000 then raise exception 'Datos de orden no válidos.';end if;
 request_id:=(payload->>'request_key')::uuid;if request_id is null then raise exception 'Falta la referencia de captura.';end if;
 signature:=encode(sha256(convert_to(b::text,'UTF8')),'hex');
 select * into old from public.prisma_order_portal_submissions where request_key=request_id;
 if found then
  if old.payload_hash<>signature then raise exception 'La captura ya fue enviada con otros datos. Recarga la lista antes de crear otra.';end if;
  select queue_number into n from public.prisma_orders where id=old.order_id;
  return jsonb_build_object('ok',true,'id',old.order_id,'queue_number',n,'duplicate',true);
 end if;
 for field,maxlen in select * from (values('folio',100),('np',100),('product',150),('pressman',100),('machine',40),('colors',1000))v(f,m) loop
  if coalesce(btrim(b->>field),'')='' or length(b->>field)>maxlen then raise exception 'Revisa el campo %.',field;end if;
 end loop;
 if length(coalesce(b->>'client',''))>150 or length(coalesce(b->>'notes',''))>1000 then raise exception 'Cliente o notas demasiado largos.';end if;
 if b->>'machine' not in ('Mark Andy','Comco 1','Comco 2','Maquina China') then raise exception 'Máquina no válida.';end if;
 if coalesce(b->>'scheduled_date','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha no válida.';end if;
 planned:=(b->>'scheduled_date')::date;
 if coalesce(b->>'scheduled_start','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or (coalesce(b->>'scheduled_end','')<>'' and b->>'scheduled_end' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') then raise exception 'Hora no válida.';end if;
 if exists(select 1 from public.prisma_orders where source='portal' and status<>'cancelled' and upper(btrim(folio))=upper(btrim(b->>'folio')) and np=btrim(b->>'np') and scheduled_date=planned) then raise exception 'Esta orden y NP ya están registrados para esa fecha. Revisa la lista.';end if;
 selections:=coalesce(b->'ink_selections','[]'::jsonb);slots:=array[]::integer[];labels:=array[]::text[];
 if jsonb_typeof(selections)<>'array' or jsonb_array_length(selections)>(case when b->>'machine' in ('Comco 1','Comco 2') then 6 else 12 end) then raise exception 'Revisa las posiciones de color.';end if;
 for selection in select value from jsonb_array_elements(selections) loop
  slot_value:=(selection->>'slot')::integer;
  if slot_value is null or slot_value<1 or slot_value>(case when b->>'machine' in ('Comco 1','Comco 2') then 6 else 12 end) or slot_value=any(slots) then raise exception 'Posición de color no válida.';end if;
  slots:=array_append(slots,slot_value);
  if coalesce(btrim(selection->>'pantone'),'')<>'' then
   if length(selection->>'pantone')>100 or nullif(selection->>'product_id','') is not null then raise exception 'Pantone no válido.';end if;
   labels:=array_append(labels,'Pantone '||btrim(selection->>'pantone'));
  else
   select * into product_row from public.prisma_products where id=(selection->>'product_id')::bigint and category='tinta';if not found then raise exception 'Tinta de catálogo no encontrada.';end if;
   labels:=array_append(labels,product_row.name||' ['||product_row.code||']');
  end if;
 end loop;
 if cardinality(labels)>0 then b:=jsonb_set(b,'{colors}',to_jsonb(array_to_string(labels,' · ')));end if;
 if nullif(b->>'die_id','') is not null then select * into die_row from public.prisma_products where id=(b->>'die_id')::bigint and category='herramental' and code like 'SJ%';if not found then raise exception 'Suaje no válido.';end if;end if;
 if nullif(b->>'crease_id','') is not null then select * into crease_row from public.prisma_products where id=(b->>'crease_id')::bigint and category='herramental' and code like 'PD%';if not found then raise exception 'Pleca no válida.';end if;end if;
 select coalesce(max(queue_number),0)+1 into n from public.prisma_orders;
 insert into public.prisma_orders(folio,np,product,client,pressman,machine,date,status,source,received_at,queue_number,scheduled_date,scheduled_start,scheduled_end,pieces,planned_meters,specifications,notes,ink_selections)
 values(btrim(b->>'folio'),btrim(b->>'np'),btrim(b->>'product'),coalesce(btrim(b->>'client'),''),btrim(b->>'pressman'),b->>'machine',public.prisma_today(),'draft','portal',clock_timestamp(),n,planned,b->>'scheduled_start',nullif(b->>'scheduled_end',''),case when nullif(b->>'pieces','') is null then null else public.prisma_number(b->>'pieces','Piezas') end,case when nullif(b->>'meters','') is null then null else public.prisma_number(b->>'meters','Metros') end,jsonb_build_object('colores',btrim(b->>'colors'))||case when die_row.id is null then '{}'::jsonb else jsonb_build_object('suaje',die_row.code||' · '||die_row.name,'die_id',die_row.id) end||case when crease_row.id is null then '{}'::jsonb else jsonb_build_object('pleca',crease_row.code||' · '||crease_row.name,'crease_id',crease_row.id) end,coalesce(btrim(b->>'notes'),''),selections) returning id into oid;
 for selection in select value from jsonb_array_elements(selections) loop
  if coalesce(btrim(selection->>'pantone'),'')<>'' then insert into public.prisma_pantone_requests(order_id,slot,pantone) values(oid,(selection->>'slot')::integer,btrim(selection->>'pantone'));end if;
 end loop;
 insert into public.prisma_order_portal_submissions values(request_id,oid,signature);
 return jsonb_build_object('ok',true,'id',oid,'queue_number',n,'duplicate',false);
end $$;
notify pgrst, 'reload schema';
commit;

-- Ejecutar TODO el archivo en SQL Editor. Luego desplegar push-notifications.
begin;
create extension if not exists pg_net with schema extensions;
create extension if not exists pg_cron with schema pg_catalog;
create table if not exists public.prisma_notification_config(id integer primary key check(id=1),public_key text not null,private_key text not null,subject text not null,dispatch_secret text not null,edge_url text not null);
create table if not exists public.prisma_notification_devices(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,device_key uuid not null,label text not null,origin text not null,endpoint text not null,p256dh text not null,auth_key text not null,enabled boolean not null default true,created_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),last_delivery_at timestamptz,last_error text,unique(user_id,device_key),unique(endpoint)
);
create table if not exists public.prisma_notification_jobs(
 id bigint generated by default as identity primary key,device_id uuid not null references public.prisma_notification_devices(id) on delete cascade,order_id bigint references public.prisma_orders(id) on delete cascade,request_key uuid unique,status text not null default 'pending',attempts integer not null default 0,due_at timestamptz not null default now(),leased_at timestamptz,created_at timestamptz not null default now(),finished_at timestamptz,last_error text
);
create unique index if not exists prisma_push_order_device on public.prisma_notification_jobs(order_id,device_id) where order_id is not null;
create index if not exists prisma_push_due_jobs on public.prisma_notification_jobs(due_at) where status in ('pending','sending');
alter table public.prisma_notification_config enable row level security;
alter table public.prisma_notification_devices enable row level security;
alter table public.prisma_notification_jobs enable row level security;
revoke all on public.prisma_notification_config,public.prisma_notification_devices,public.prisma_notification_jobs from public,anon,authenticated;
create or replace function public.prisma_push_endpoint_allowed(endpoint text) returns boolean language sql immutable set search_path=public,pg_temp as $$
 select endpoint ~ '^https://(fcm[.]googleapis[.]com|fcmregistrations[.]googleapis[.]com|updates[.]push[.]services[.]mozilla[.]com|web[.]push[.]apple[.]com|[a-z0-9-]+[.]notify[.]windows[.]com)/[^[:space:]#]+$' and length(endpoint)<=3000;
$$;
create or replace function public.prisma_wake_push() returns boolean language plpgsql security definer set search_path=public,pg_temp as $$
declare c public.prisma_notification_config%rowtype;
begin
 if not exists(select 1 from public.prisma_notification_jobs where (status='pending' and due_at<=now()) or (status='sending' and leased_at<now()-interval '3 minutes')) then return false;end if;
 select * into c from public.prisma_notification_config where id=1;if not found then return false;end if;
 perform net.http_post(url:=c.edge_url,headers:=jsonb_build_object('Content-Type','application/json','X-Dispatch-Key',c.dispatch_secret),body:='{"action":"dispatch"}'::jsonb,timeout_milliseconds:=5000);
 return true;
exception when others then return false; -- La recepción de órdenes no depende del proveedor push.
end $$;
create or replace function public.prisma_devices(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
<<devices>>
declare op text:=payload->>'operation';saved_device_id uuid;device_key_value uuid;target public.prisma_notification_devices%rowtype;endpoint_value text;origin_value text;result jsonb;request_id uuid;
begin
 perform public.prisma_authorize();
 if op='register' then
  device_key_value:=(payload->>'device_key')::uuid;endpoint_value:=payload->'subscription'->>'endpoint';origin_value:=payload->>'origin';
  if device_key_value is null or not coalesce(public.prisma_push_endpoint_allowed(endpoint_value),false) or origin_value is null or (origin_value !~ '^https://[a-zA-Z0-9.-]+(:[0-9]+)?$' and origin_value !~ '^http://(localhost|127[.]0[.]0[.]1)(:[0-9]+)?$') then raise exception 'Dispositivo o dirección de notificaciones no válida.';end if;
  if coalesce(payload->'subscription'->'keys'->>'p256dh','') !~ '^[A-Za-z0-9_-]{80,100}$' or coalesce(payload->'subscription'->'keys'->>'auth','') !~ '^[A-Za-z0-9_-]{16,40}$' then raise exception 'Suscripción de notificaciones no válida.';end if;
  if coalesce(btrim(payload->>'label'),'')='' or length(payload->>'label')>80 then raise exception 'Escribe un nombre de hasta 80 caracteres.';end if;
  perform pg_advisory_xact_lock(hashtext(auth.uid()::text));
  if exists(select 1 from public.prisma_notification_devices where endpoint=endpoint_value and user_id<>auth.uid()) then raise exception 'Este navegador está asociado a otra cuenta. Desactívalo en esa cuenta primero.';end if;
  update public.prisma_notification_devices d set device_key=device_key_value where d.user_id=auth.uid() and d.endpoint=endpoint_value and d.device_key<>device_key_value and not exists(select 1 from public.prisma_notification_devices x where x.user_id=auth.uid() and x.device_key=device_key_value);
  if not exists(select 1 from public.prisma_notification_devices where user_id=auth.uid() and device_key=device_key_value) and (select count(*) from public.prisma_notification_devices where user_id=auth.uid())>=20 then raise exception 'Puedes registrar hasta 20 dispositivos. Elimina uno anterior.';end if;
  insert into public.prisma_notification_devices(user_id,device_key,label,origin,endpoint,p256dh,auth_key)
  values(auth.uid(),device_key_value,btrim(payload->>'label'),origin_value,endpoint_value,payload->'subscription'->'keys'->>'p256dh',payload->'subscription'->'keys'->>'auth')
  on conflict(user_id,device_key) do update set label=excluded.label,origin=excluded.origin,endpoint=excluded.endpoint,p256dh=excluded.p256dh,auth_key=excluded.auth_key,enabled=true,last_seen_at=now(),last_error=null returning id into saved_device_id;
  return jsonb_build_object('id',saved_device_id,'enabled',true);
 elsif op in ('disable','remove','rename','test') then
  select * into target from public.prisma_notification_devices where user_id=auth.uid() and id=(payload->>'id')::uuid for update;if not found then raise exception 'Dispositivo no encontrado.';end if;
  if op='disable' then
   update public.prisma_notification_devices set enabled=false where id=target.id;
   update public.prisma_notification_jobs set status='skipped',finished_at=now() where device_id=target.id and status in ('pending','sending');
  elsif op='remove' then delete from public.prisma_notification_devices where id=target.id;
  elsif op='rename' then
   if coalesce(btrim(payload->>'label'),'')='' or length(payload->>'label')>80 then raise exception 'Nombre no válido.';end if;
   update public.prisma_notification_devices set label=btrim(payload->>'label') where id=target.id;
  else
   if not target.enabled then raise exception 'Activa las notificaciones del dispositivo primero.';end if;
   request_id:=(payload->>'request_key')::uuid;if request_id is null then raise exception 'Falta la referencia de la prueba.';end if;
   if exists(select 1 from public.prisma_notification_jobs where request_key=request_id and device_id<>target.id) then raise exception 'Referencia de prueba no válida.';end if;
   if not exists(select 1 from public.prisma_notification_jobs where request_key=request_id) and exists(select 1 from public.prisma_notification_jobs where device_id=target.id and order_id is null and created_at>now()-interval '30 seconds') then raise exception 'Espera 30 segundos antes de otra prueba.';end if;
   insert into public.prisma_notification_jobs(device_id,request_key) values(target.id,request_id) on conflict(request_key) do nothing;
   perform public.prisma_wake_push();
  end if;
  return jsonb_build_object('ok',true);
 elsif op is distinct from 'list' then raise exception 'Acción de dispositivo no válida.';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'device_key',d.device_key,'label',d.label,'origin',d.origin,'enabled',d.enabled,'last_seen_at',d.last_seen_at,'last_delivery_at',d.last_delivery_at,'last_error',d.last_error) order by d.created_at),'[]'::jsonb) into result from public.prisma_notification_devices d where d.user_id=auth.uid();
 return jsonb_build_object('devices',result,'push_configured',exists(select 1 from public.prisma_notification_config where id=1));
end $$;
create or replace function public.prisma_queue_order_push() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 insert into public.prisma_notification_jobs(device_id,order_id)
 select d.id,new.id from public.prisma_notification_devices d join public.prisma_members m on m.user_id=d.user_id where d.enabled on conflict do nothing;
 perform public.prisma_wake_push();return new;
end $$;
drop trigger if exists queue_order_push on public.prisma_orders;
create trigger queue_order_push after insert on public.prisma_orders for each row execute function public.prisma_queue_order_push();
-- Solo la función de servidor usa las siguientes RPC; las claves nunca se envían al navegador.
create or replace function public.prisma_push_configuration(candidate jsonb default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if candidate is not null then
  if coalesce(candidate->>'edge_url','') !~ '^https://[a-z0-9]+[.]supabase[.]co/functions/v1/push-notifications$' then raise exception 'URL de función no válida.';end if;
  insert into public.prisma_notification_config(id,public_key,private_key,subject,dispatch_secret,edge_url) values(1,candidate->>'public_key',candidate->>'private_key',candidate->>'subject',candidate->>'dispatch_secret',candidate->>'edge_url') on conflict(id) do nothing;
 end if;
 select to_jsonb(c) into result from public.prisma_notification_config c where id=1;return result;
end $$;
create or replace function public.prisma_claim_push_jobs() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare result jsonb;
begin
 update public.prisma_notification_jobs set status='failed',finished_at=now(),last_error='PUSH_RETRIES_EXHAUSTED' where status='sending' and attempts>=5 and leased_at<now()-interval '3 minutes';
 update public.prisma_notification_jobs j set status='skipped',finished_at=now() where j.status in ('pending','sending') and not exists(select 1 from public.prisma_notification_devices d join public.prisma_members m on m.user_id=d.user_id where d.id=j.device_id and d.enabled);
 with picked as (
  select j.id from public.prisma_notification_jobs j where j.attempts<5 and ((j.status='pending' and j.due_at<=now()) or (j.status='sending' and j.leased_at<now()-interval '3 minutes')) order by j.id for update skip locked limit 20
 ),claimed as (
  update public.prisma_notification_jobs j set status='sending',attempts=attempts+1,leased_at=now() from picked where j.id=picked.id returning j.*
 ) select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'attempt',j.attempts,'device_id',d.id,'subscription',jsonb_build_object('endpoint',d.endpoint,'keys',jsonb_build_object('p256dh',d.p256dh,'auth',d.auth_key)),'payload',jsonb_build_object('eventId','push-'||j.id,'deviceKey',d.device_key,'title',case when j.order_id is null then 'Notificaciones activadas' else 'Nueva orden de producción' end,'body',case when j.order_id is null then 'Este dispositivo puede recibir avisos de órdenes nuevas.' else left(o.folio||case when coalesce(o.np,'')<>'' then ' · NP '||o.np else '' end,180) end,'url','/#preparacion'))),'[]'::jsonb) into result from claimed j join public.prisma_notification_devices d on d.id=j.device_id left join public.prisma_orders o on o.id=j.order_id;
 return result;
end $$;
create or replace function public.prisma_finish_push_job(payload jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare j public.prisma_notification_jobs%rowtype;successful boolean:=coalesce((payload->>'success')::boolean,false);retired boolean:=coalesce((payload->>'retired')::boolean,false);reason text:=left(coalesce(payload->>'reason','PUSH_ERROR'),80);
begin
 select * into j from public.prisma_notification_jobs where id=(payload->>'id')::bigint and status='sending' and attempts=(payload->>'attempt')::integer for update;if not found then return;end if;
 update public.prisma_notification_jobs set status=case when successful then 'sent' when retired then 'skipped' when attempts>=5 then 'failed' else 'pending' end,finished_at=case when successful or retired or attempts>=5 then now() else null end,due_at=now()+make_interval(secs=>least(900,30*power(2,j.attempts)::integer)),last_error=case when successful then null else reason end where id=j.id;
 update public.prisma_notification_devices set last_delivery_at=case when successful then now() else last_delivery_at end,last_error=case when successful then null else reason end,enabled=case when retired then false else enabled end where id=j.device_id;
end $$;
revoke all on function public.prisma_push_endpoint_allowed(text),public.prisma_wake_push(),public.prisma_devices(jsonb),public.prisma_queue_order_push(),public.prisma_push_configuration(jsonb),public.prisma_claim_push_jobs(),public.prisma_finish_push_job(jsonb) from public,anon,authenticated;
grant execute on function public.prisma_devices(jsonb) to authenticated;
grant execute on function public.prisma_push_configuration(jsonb),public.prisma_claim_push_jobs(),public.prisma_finish_push_job(jsonb) to service_role;
do $$ begin
 if exists(select 1 from cron.job where jobname='inventory-push-retry') then perform cron.unschedule('inventory-push-retry');end if;
 perform cron.schedule('inventory-push-retry','* * * * *','select public.prisma_wake_push()');
end $$;
notify pgrst, 'reload schema';
commit;

-- Account approval, module permissions and session audit (apply last).
-- Ejecutar completo. No cambia existencias ni incorpora usuarios nuevos al inventario automáticamente.
begin;
create table if not exists public.prisma_admins(user_id uuid primary key references auth.users(id) on delete cascade);
alter table public.prisma_members add column if not exists permissions text[] not null default array['inventory','movements','catalog','production','preparation','incidents','cuts','devices','settings'];
create table if not exists public.prisma_account_decisions(user_id uuid primary key references auth.users(id) on delete cascade,status text not null,reviewer uuid references auth.users(id) on delete set null,reviewed_at timestamptz not null default now());
create table if not exists public.prisma_login_sessions(session_id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,device_key uuid not null,device_name text not null,browser text not null,platform text not null,origin text not null,created_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),ended_at timestamptz);
alter table public.prisma_admins enable row level security;
alter table public.prisma_account_decisions enable row level security;
alter table public.prisma_login_sessions enable row level security;
revoke all on public.prisma_admins,public.prisma_account_decisions,public.prisma_login_sessions from public,anon,authenticated;
-- Toda primera lectura autorizada registra al menos la sesión, incluso con un cliente antiguo.
create or replace function public.prisma_authorize() returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare sid uuid;headers jsonb;
begin
 if auth.uid() is null or not exists(select 1 from public.prisma_members where user_id=auth.uid()) then raise exception 'Tu cuenta no tiene acceso a este inventario.';end if;
 sid:=nullif(auth.jwt()->>'session_id','')::uuid;
 if sid is not null then
  if exists(select 1 from public.prisma_login_sessions where session_id=sid and user_id=auth.uid() and ended_at is not null) then raise exception 'Esta sesión ya se cerró. Inicia sesión de nuevo.';end if;
  headers:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;
  insert into public.prisma_login_sessions(session_id,user_id,device_key,device_name,browser,platform,origin) values(sid,auth.uid(),gen_random_uuid(),'Navegador sin registro','','',left(coalesce(headers->>'origin','No informado'),500)) on conflict(session_id) do nothing;
 end if;
end $$;
-- Solo reconoce al propietario si YA estaba autorizado, nunca a un registro público nuevo.
insert into public.prisma_admins(user_id) select u.id from auth.users u join public.prisma_members m on m.user_id=u.id where lower(u.email)='chinofidelemiliano@gmail.com' and u.email_confirmed_at is not null on conflict do nothing;
create or replace function public.prisma_has_permission(person uuid,permission_name text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select exists(select 1 from public.prisma_admins where user_id=person) or exists(select 1 from public.prisma_members where user_id=person and permission_name=any(permissions));
$$;
create or replace function public.prisma_require_admin() returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin perform public.prisma_authorize();if auth.uid() is null or not exists(select 1 from public.prisma_admins where user_id=auth.uid()) then raise exception 'Solo el administrador puede realizar esta acción.';end if;end $$;
create or replace function public.prisma_require_permission(permission_name text) returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin perform public.prisma_authorize();if not public.prisma_has_permission(auth.uid(),permission_name) then raise exception 'No tienes permiso para este apartado.';end if;end $$;
create or replace function public.prisma_account_access() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare member public.prisma_members%rowtype;person auth.users%rowtype;decision text;
begin
 if auth.uid() is null then raise exception 'Inicia sesión para continuar.';end if;
 select * into person from auth.users where id=auth.uid();select * into member from public.prisma_members where user_id=auth.uid();select status into decision from public.prisma_account_decisions where user_id=auth.uid();
 return jsonb_build_object('email',person.email,'approved',member.user_id is not null,'email_verified',person.email_confirmed_at is not null and (member.user_id is not null or (person.confirmation_sent_at is not null and person.email_confirmed_at>=person.confirmation_sent_at)),'is_admin',exists(select 1 from public.prisma_admins where user_id=auth.uid()),'permissions',coalesce(to_jsonb(member.permissions),'[]'::jsonb),'session_closed',exists(select 1 from public.prisma_login_sessions where session_id=nullif(auth.jwt()->>'session_id','')::uuid and user_id=auth.uid() and ended_at is not null),'status',case when member.user_id is not null then 'approved' else coalesce(decision,'pending') end);
end $$;
create or replace function public.prisma_admin_accounts(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare target uuid;person auth.users%rowtype;allowed text[]:=array['inventory','movements','catalog','production','preparation','incidents','cuts','devices','settings'];requested text[];op text:=payload->>'operation';result jsonb;
begin
 perform public.prisma_require_admin();
 if op in ('approve','revoke','reject') then
  target:=(payload->>'user_id')::uuid;select * into person from auth.users where id=target;if not found then raise exception 'Cuenta no encontrada.';end if;
  if exists(select 1 from public.prisma_admins where user_id=target) then raise exception 'No puedes cambiar el acceso de una cuenta administradora desde esta pantalla.';end if;
  if op='approve' then
   if person.email_confirmed_at is null or (not exists(select 1 from public.prisma_members where user_id=target) and (person.confirmation_sent_at is null or person.email_confirmed_at<person.confirmation_sent_at)) then raise exception 'La cuenta debe verificar su correo con el código antes de autorizarla.';end if;
   if jsonb_typeof(payload->'permissions') is distinct from 'array' then raise exception 'Selecciona los permisos.';end if;
   select array_agg(distinct value) into requested from jsonb_array_elements_text(payload->'permissions');
   if coalesce(cardinality(requested),0)=0 or not requested<@allowed then raise exception 'Selecciona al menos un permiso válido.';end if;
   insert into public.prisma_members(user_id,permissions) values(target,requested) on conflict(user_id) do update set permissions=excluded.permissions;
  else
   delete from public.prisma_members where user_id=target;
   if to_regclass('public.prisma_notification_devices') is not null then update public.prisma_notification_devices set enabled=false where user_id=target;end if;
  end if;
  insert into public.prisma_account_decisions(user_id,status,reviewer) values(target,case when op='approve' then 'approved' when op='reject' then 'rejected' else 'revoked' end,auth.uid()) on conflict(user_id) do update set status=excluded.status,reviewer=excluded.reviewer,reviewed_at=now();
 elsif op is distinct from 'list' then raise exception 'Acción no válida.';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'email',u.email,'name',left(coalesce(u.raw_user_meta_data->>'display_name',''),100),'created_at',u.created_at,'email_verified',u.email_confirmed_at is not null and (m.user_id is not null or (u.confirmation_sent_at is not null and u.email_confirmed_at>=u.confirmation_sent_at)),'approved',m.user_id is not null,'is_admin',a.user_id is not null,'permissions',coalesce(to_jsonb(m.permissions),'[]'::jsonb),'status',case when m.user_id is not null then 'approved' else coalesce(d.status,'pending') end) order by u.created_at desc),'[]'::jsonb) into result from auth.users u left join public.prisma_members m on m.user_id=u.id left join public.prisma_admins a on a.user_id=u.id left join public.prisma_account_decisions d on d.user_id=u.id;
 return jsonb_build_object('accounts',result);
end $$;
create or replace function public.prisma_login_activity(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare sid uuid;op text:=payload->>'operation';record public.prisma_login_sessions%rowtype;origin_value text:=payload->>'origin';
begin
 if auth.uid() is null then raise exception 'Inicia sesión para continuar.';end if;
 sid:=nullif(auth.jwt()->>'session_id','')::uuid;if sid is null then raise exception 'Vuelve a iniciar sesión para registrar este dispositivo.';end if;
 if op='login' then
  if origin_value is null or (origin_value !~ '^https://[a-zA-Z0-9.-]+(:[0-9]+)?$' and origin_value !~ '^http://(localhost|127[.]0[.]0[.]1)(:[0-9]+)?$') or coalesce(btrim(payload->>'device_name'),'')='' or length(payload->>'device_name')>100 or length(coalesce(payload->>'browser',''))>80 or length(coalesce(payload->>'platform',''))>80 then raise exception 'Información de dispositivo no válida.';end if;
  insert into public.prisma_login_sessions(session_id,user_id,device_key,device_name,browser,platform,origin) values(sid,auth.uid(),(payload->>'device_key')::uuid,btrim(payload->>'device_name'),coalesce(payload->>'browser',''),coalesce(payload->>'platform',''),origin_value)
  on conflict(session_id) do update set last_seen_at=now(),device_key=excluded.device_key,device_name=excluded.device_name,browser=excluded.browser,platform=excluded.platform,origin=excluded.origin where prisma_login_sessions.user_id=auth.uid() and prisma_login_sessions.ended_at is null;
 elsif op='heartbeat' then update public.prisma_login_sessions set last_seen_at=now() where session_id=sid and user_id=auth.uid() and ended_at is null;
 elsif op='logout' then update public.prisma_login_sessions set last_seen_at=now(),ended_at=coalesce(ended_at,now()) where session_id=sid and user_id=auth.uid();
 else raise exception 'Acción de sesión no válida.';end if;
 return jsonb_build_object('ok',true);
end $$;
create or replace function public.prisma_admin_login_sessions(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare result jsonb;target public.prisma_login_sessions%rowtype;
begin
 perform public.prisma_require_admin();
 if payload->>'operation'='close' then
  if (payload->>'session_id')::uuid=nullif(auth.jwt()->>'session_id','')::uuid then raise exception 'Usa Cerrar sesión para terminar tu sesión actual.';end if;
  select * into target from public.prisma_login_sessions where session_id=(payload->>'session_id')::uuid;if not found then raise exception 'Sesión no encontrada.';end if;
  update public.prisma_login_sessions set ended_at=coalesce(ended_at,now()) where session_id=target.session_id;
  if to_regclass('public.prisma_notification_devices') is not null then update public.prisma_notification_devices set enabled=false where user_id=target.user_id and device_key=target.device_key and origin=target.origin;end if;
 elsif payload->>'operation' is distinct from 'list' then raise exception 'Acción de sesión no válida.';end if;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) into result from (select s.session_id,s.user_id,u.email,s.device_name,s.browser,s.platform,s.origin,s.created_at,s.last_seen_at,s.ended_at,s.session_id=nullif(auth.jwt()->>'session_id','')::uuid as current_session from public.prisma_login_sessions s join auth.users u on u.id=s.user_id order by s.created_at desc limit 200)x;return jsonb_build_object('sessions',result);
end $$;
