-- Profile-managed ink choices for shared order capture.
-- Ejecutar completo después de accounts-and-sessions.sql. Conserva órdenes e inventario.
begin;
create table if not exists public.prisma_order_ink_settings(id integer primary key check(id=1),owner_id uuid references auth.users(id) on delete set null,options jsonb not null default '[]',updated_at timestamptz not null default now());
alter table public.prisma_order_ink_settings enable row level security;
revoke all on public.prisma_order_ink_settings from public,anon,authenticated;
create or replace function public.prisma_order_ink_options(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare options jsonb;item jsonb;p public.prisma_products%rowtype;seen text[]:=array[]::text[];
begin
 perform public.prisma_require_admin();
 if payload->>'operation'='save' then
  options:=payload->'options';if jsonb_typeof(options) is distinct from 'array' or jsonb_array_length(options)>100 then raise exception 'Configura hasta 100 tintas personalizadas.';end if;
  for item in select value from jsonb_array_elements(options) loop
   if coalesce(item->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or item->>'id'=any(seen) or coalesce(btrim(item->>'label'),'')='' or length(item->>'label')>80 or coalesce(item->>'family','') not in ('Base Agua','UV','Film') then raise exception 'Revisa las opciones personalizadas.';end if;
   seen:=array_append(seen,item->>'id');
   if nullif(item->>'product_id','') is not null then
    select * into p from public.prisma_products where id=(item->>'product_id')::bigint and category='tinta';
    if not found or (item->>'family'='UV' and lower(btrim(p.kind))<>'uv') or (item->>'family'='Film' and lower(btrim(p.kind))<>'film') or (item->>'family'='Base Agua' and lower(btrim(p.kind)) not in ('base agua','base de agua','agua')) then raise exception 'La tinta relacionada debe ser del mismo tipo.';end if;
   end if;
  end loop;
  insert into public.prisma_order_ink_settings(id,owner_id,options) values(1,auth.uid(),options) on conflict(id) do update set owner_id=auth.uid(),options=excluded.options,updated_at=now();
 elsif payload->>'operation' is distinct from 'get' then raise exception 'Acción no válida.';end if;
 return jsonb_build_object('options',coalesce((select s.options from public.prisma_order_ink_settings s where id=1),'[]'::jsonb));
end $$;
revoke all on function public.prisma_order_ink_options(jsonb) from public,anon,authenticated;
grant execute on function public.prisma_order_ink_options(jsonb) to authenticated;
do $$begin
 if to_regprocedure('public.prisma_order_portal_ink_internal(text,jsonb)') is null then alter function public.prisma_order_portal(text,jsonb) rename to prisma_order_portal_ink_internal;end if;
end $$;
revoke all on function public.prisma_order_portal_ink_internal(text,jsonb) from public,anon,authenticated;
create or replace function public.prisma_order_portal(access_key text,payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare result jsonb;options jsonb;item jsonb;custom jsonb;selections jsonb:='[]';b jsonb:=payload->'order';family text;global_family text:=b->>'ink_family';families text[]:=array[]::text[];labels text[]:=array[]::text[];label_value text;summary text;p public.prisma_products%rowtype;entry jsonb;
begin
 -- Always validate the private capture link using the existing restricted function first.
 if payload->>'operation'<>'submit' then
  result:=public.prisma_order_portal_ink_internal(access_key,payload);
  if payload->>'operation'='catalog' then return result||jsonb_build_object('ink_options',coalesce((select s.options from public.prisma_order_ink_settings s where id=1),'[]'::jsonb));end if;
  if payload->>'operation'='list' then
   select coalesce(jsonb_agg(value||jsonb_build_object('ink_family',coalesce((select specifications->>'tipo_tinta' from public.prisma_orders where id=(value->>'id')::bigint),''))),'[]'::jsonb) into selections from jsonb_array_elements(result->'orders');return jsonb_set(result,'{orders}',selections);
  end if;
  return result;
 end if;
 -- A catalog call checks the link before reading configuration or validating submitted products.
 perform public.prisma_order_portal_ink_internal(access_key,jsonb_build_object('operation','catalog'));
 if nullif(b->>'meters','') is null or (b->>'meters')::numeric<=0 or (b->>'meters')::numeric>1e12 then raise exception 'Captura un metraje mayor que cero.';end if;
 if global_family is not null and global_family not in ('Base Agua','UV','Film') then raise exception 'Selecciona Base Agua, UV o Film.';end if;
 options:=coalesce((select s.options from public.prisma_order_ink_settings s where id=1),'[]'::jsonb);
 for item in select value from jsonb_array_elements(coalesce(b->'ink_selections','[]'::jsonb)) loop
  family:=coalesce(item->>'ink_family',global_family);if family is not null and family not in ('Base Agua','UV','Film') then raise exception 'Selecciona Base Agua, UV o Film en cada tinta.';end if;entry:=item;
  if coalesce(item->>'custom_id','')<>'' then
   select value into custom from jsonb_array_elements(options) where value->>'id'=item->>'custom_id' and value->>'family'=family;
   if custom is null then raise exception 'La tinta personalizada cambió. Actualiza el catálogo.';end if;
   entry:=jsonb_build_object('slot',item->'slot','product_id',custom->'product_id','pantone',case when nullif(custom->>'product_id','') is null then custom->>'label'||' ('||family||')' else '' end);
  end if;
  if nullif(entry->>'product_id','') is not null then
   select * into p from public.prisma_products where id=(entry->>'product_id')::bigint and category='tinta';
   if not found or (family='UV' and lower(btrim(p.kind))<>'uv') or (family='Film' and lower(btrim(p.kind))<>'film') or (family='Base Agua' and lower(btrim(p.kind)) not in ('base agua','base de agua','agua')) then raise exception 'La tinta no corresponde al tipo seleccionado.';end if;
  end if;
  if family is not null then
   if item ? 'ink_family' then entry:=entry||jsonb_build_object('ink_family',family);end if;families:=array_append(families,family);
  end if;
  if item ? 'ink_family' and coalesce(item->>'custom_id','')='' and coalesce(btrim(entry->>'pantone'),'')<>'' then entry:=jsonb_set(entry,'{pantone}',to_jsonb((entry->>'pantone')||' ('||family||')'));end if;
  label_value:=case when coalesce(btrim(entry->>'pantone'),'')<>'' then 'Pantone '||(entry->>'pantone') else p.name||' ['||p.code||']'||case when family is null then '' else ' ('||family||')' end end;
  labels:=array_append(labels,label_value);
  selections:=selections||jsonb_build_array(entry);
 end loop;
 result:=public.prisma_order_portal_ink_internal(access_key,jsonb_set(payload,'{order,ink_selections}',selections));
 if cardinality(families)>0 then select array_agg(f order by array_position(array['Base Agua','UV','Film'],f)) into families from (select distinct unnest(families) as f)x;summary:=case when cardinality(families)>1 then 'Mixta ('||array_to_string(families,' + ')||')' else families[1] end;elsif global_family is not null then summary:=global_family;end if;
 if summary is not null then update public.prisma_orders set specifications=specifications||jsonb_build_object('tipo_tinta',summary,'colores',array_to_string(labels,' · ')) where id=(result->>'id')::bigint;end if;
 return result;
end $$;
revoke all on function public.prisma_order_portal(text,jsonb) from public,anon,authenticated;
grant execute on function public.prisma_order_portal(text,jsonb) to anon,authenticated;
notify pgrst,'reload schema';
commit;

-- Read-only monthly order status links and independent order comments.
begin;
create table if not exists public.prisma_order_comments(id bigint generated by default as identity primary key,order_id bigint not null references public.prisma_orders(id),body text not null check(length(body) between 1 and 2000),author text not null,user_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.prisma_order_status_access(id integer primary key check(id=1),token_hash text not null,enabled boolean not null default true);
create table if not exists public.prisma_order_status_months(month text primary key,report jsonb not null,updated_at timestamptz not null default now());
alter table public.prisma_order_comments enable row level security;
alter table public.prisma_order_status_access enable row level security;
alter table public.prisma_order_status_months enable row level security;
revoke all on public.prisma_order_comments,public.prisma_order_status_access,public.prisma_order_status_months from public,anon,authenticated;
create or replace function public.prisma_order_comments(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare oid bigint:=(payload->>'order_id')::bigint;author_name text;result jsonb;
begin
 perform public.prisma_authorize();if not public.prisma_has_permission(auth.uid(),'production') and not public.prisma_has_permission(auth.uid(),'preparation') then raise exception 'No tienes permiso para comentar órdenes.';end if;
 if not exists(select 1 from public.prisma_orders where id=oid) then raise exception 'Orden no encontrada.';end if;
 if payload->>'operation'='add' then
  if coalesce(btrim(payload->>'body'),'')='' or length(payload->>'body')>2000 then raise exception 'Escribe un comentario de hasta 2000 caracteres.';end if;
  select left(coalesce(nullif(btrim(p.preferences->>'reportName'),''),nullif(btrim(u.raw_user_meta_data->>'full_name'),''),nullif(btrim(u.raw_user_meta_data->>'display_name'),''),'Usuario autorizado'),100) into author_name from auth.users u left join public.prisma_user_preferences p on p.user_id=u.id where u.id=auth.uid();
  insert into public.prisma_order_comments(order_id,body,author,user_id) values(oid,btrim(payload->>'body'),coalesce(author_name,'Usuario autorizado'),auth.uid());
 elsif payload->>'operation' is distinct from 'list' then raise exception 'Acción no válida.';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'body',body,'author',author,'created_at',created_at) order by id),'[]'::jsonb) into result from public.prisma_order_comments where order_id=oid;return jsonb_build_object('comments',result);
end $$;
create or replace function public.prisma_refresh_order_status_month(target_month text) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare report_value jsonb;
begin
 select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'folio',o.folio,'np',o.np,'product',o.product,'client',o.client,'machine',o.machine,'pressman',o.pressman,'scheduled_date',coalesce(o.scheduled_date,o.date),'scheduled_start',o.scheduled_start,'scheduled_end',o.scheduled_end,'started_at',o.started_at,'ended_at',o.ended_at,'meters',o.planned_meters,'queue_number',o.queue_number,'status',case when o.status='cancelled' then 'Cancelada' when o.status='confirmed' then 'Cerrada' when o.ended_at is not null then 'Preparada' when o.started_at is not null then 'En preparación' else 'En espera' end) order by o.queue_number nulls last,o.id),'[]'::jsonb) into report_value from public.prisma_orders o where to_char(coalesce(o.scheduled_date,o.date),'YYYY-MM')=target_month;
 insert into public.prisma_order_status_months(month,report) values(target_month,report_value) on conflict(month) do update set report=excluded.report,updated_at=now();
end $$;
create or replace function public.prisma_archive_order_status() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform public.prisma_refresh_order_status_month(to_char(coalesce(new.scheduled_date,new.date),'YYYY-MM'));
 if tg_op='UPDATE' and to_char(coalesce(old.scheduled_date,old.date),'YYYY-MM')<>to_char(coalesce(new.scheduled_date,new.date),'YYYY-MM') then perform public.prisma_refresh_order_status_month(to_char(coalesce(old.scheduled_date,old.date),'YYYY-MM'));end if;return new;
end $$;
drop trigger if exists prisma_archive_order_status on public.prisma_orders;
create trigger prisma_archive_order_status after insert or update on public.prisma_orders for each row execute function public.prisma_archive_order_status();
do $$declare m text;begin for m in select distinct to_char(coalesce(scheduled_date,date),'YYYY-MM') from public.prisma_orders loop perform public.prisma_refresh_order_status_month(m);end loop;end $$;
create or replace function public.prisma_manage_order_status(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare secret text;
begin
 perform public.prisma_require_admin();if payload->>'operation'='configure' then secret:='st_'||encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex');insert into public.prisma_order_status_access values(1,encode(sha256(convert_to(secret,'UTF8')),'hex'),true) on conflict(id) do update set token_hash=excluded.token_hash,enabled=true;
 elsif payload->>'operation'='disable' then update public.prisma_order_status_access set enabled=false where id=1;
 elsif payload->>'operation' is distinct from 'status' then raise exception 'Acción no válida.';end if;
 return jsonb_build_object('enabled',coalesce((select enabled from public.prisma_order_status_access where id=1),false),'access_key',secret);
end $$;
create or replace function public.prisma_order_status(access_key text,target_month text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare m text:=coalesce(target_month,to_char(public.prisma_today(),'YYYY-MM'));report_value jsonb;months jsonb;stamp timestamptz;
begin
 if access_key is null or access_key !~ '^st_[a-f0-9]{64}$' or not exists(select 1 from public.prisma_order_status_access where id=1 and enabled and token_hash=encode(sha256(convert_to(access_key,'UTF8')),'hex')) then raise exception 'El enlace de consulta no está autorizado o fue desactivado.';end if;
 if m !~ '^\d{4}-(0[1-9]|1[0-2])$' then raise exception 'Mes no válido.';end if;
 select report,updated_at into report_value,stamp from public.prisma_order_status_months where month=m;
 select jsonb_agg(month order by month desc) into months from (select month from public.prisma_order_status_months union select to_char(public.prisma_today(),'YYYY-MM') union select m)x;
 return jsonb_build_object('month',m,'months',months,'orders',coalesce(report_value,'[]'::jsonb),'updated_at',coalesce(stamp,now()));
end $$;
revoke all on function public.prisma_order_comments(jsonb),public.prisma_refresh_order_status_month(text),public.prisma_archive_order_status(),public.prisma_manage_order_status(jsonb),public.prisma_order_status(text,text) from public,anon,authenticated;
grant execute on function public.prisma_order_comments(jsonb),public.prisma_manage_order_status(jsonb) to authenticated;
grant execute on function public.prisma_order_status(text,text) to anon,authenticated;
notify pgrst,'reload schema';
commit;

-- Password gate for shared monthly order status (apply after status functions).
-- Ejecutar después de order-status-and-comments.sql. No cambia el enlace de consulta.
begin;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create table if not exists public.prisma_order_status_credentials(id integer primary key check(id=1),username text not null,password_hash text not null,failed_attempts integer not null default 0,window_started timestamptz not null default now());
create table if not exists public.prisma_order_status_sessions(session_hash text primary key,link_hash text not null,expires_at timestamptz not null);
alter table public.prisma_order_status_credentials enable row level security;
alter table public.prisma_order_status_sessions enable row level security;
revoke all on public.prisma_order_status_credentials,public.prisma_order_status_sessions from public,anon,authenticated;
insert into public.prisma_order_status_credentials(id,username,password_hash) values(1,'1','$2a$10$kOAYBoFCphHMgWTVJlbLjun2o02Sm5MOiwXmHuL5KOMU0kzkvXVfW') on conflict(id) do nothing;
create or replace function public.prisma_status_password_matches(candidate text,stored_hash text) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$
declare extension_schema text;matches boolean;
begin
 select n.nspname into extension_schema from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname='pgcrypto';
 if extension_schema is null then raise exception 'Falta activar pgcrypto.';end if;
 execute format('select %I.crypt($1,$2)=$2',extension_schema) into matches using candidate,stored_hash;return matches;
end $$;
create or replace function public.prisma_order_status_login(access_key text,login_user text,login_password text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare credential public.prisma_order_status_credentials%rowtype;secret text;link_digest text;
begin
 link_digest:=encode(sha256(convert_to(coalesce(access_key,''),'UTF8')),'hex');
 if access_key is null or access_key !~ '^st_[a-f0-9]{64}$' or not exists(select 1 from public.prisma_order_status_access where id=1 and enabled and token_hash=link_digest) then return jsonb_build_object('error','El enlace de consulta no está autorizado o fue desactivado.');end if;
 select * into credential from public.prisma_order_status_credentials where id=1 for update;
 if not found then return jsonb_build_object('error','Falta configurar el acceso de consulta.');end if;
 if credential.window_started<now()-interval '10 minutes' then update public.prisma_order_status_credentials set failed_attempts=0,window_started=now() where id=1 returning * into credential;end if;
 if credential.failed_attempts>=10 then return jsonb_build_object('error','Demasiados intentos. Intenta nuevamente en 10 minutos.');end if;
 if login_user is null or login_password is null or length(login_user)>100 or length(login_password)>128 or btrim(login_user)<>credential.username or not public.prisma_status_password_matches(login_password,credential.password_hash) then update public.prisma_order_status_credentials set failed_attempts=failed_attempts+1 where id=1;return jsonb_build_object('error','Usuario o contraseña incorrectos.');end if;
 update public.prisma_order_status_credentials set failed_attempts=0,window_started=now() where id=1;
 delete from public.prisma_order_status_sessions where expires_at<=now();
 secret:='ss_'||encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex');
 insert into public.prisma_order_status_sessions values(encode(sha256(convert_to(secret,'UTF8')),'hex'),link_digest,now()+interval '1 hour');
 return jsonb_build_object('session_key',secret,'expires_at',now()+interval '1 hour');
end $$;
do $$begin
 if to_regprocedure('public.prisma_order_status_read_internal(text,text)') is null then alter function public.prisma_order_status(text,text) rename to prisma_order_status_read_internal;end if;
end $$;
-- Close the old two-argument route as well if an older migration was rerun later.
revoke all on function public.prisma_order_status_read_internal(text,text) from public,anon,authenticated;
drop function if exists public.prisma_order_status(text,text);
create or replace function public.prisma_order_status(access_key text,target_month text,session_key text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if session_key is null or not exists(select 1 from public.prisma_order_status_sessions where session_hash=encode(sha256(convert_to(session_key,'UTF8')),'hex') and link_hash=encode(sha256(convert_to(coalesce(access_key,''),'UTF8')),'hex') and expires_at>now()) then raise exception 'Inicia sesión para consultar las órdenes.';end if;
 return public.prisma_order_status_read_internal(access_key,target_month);
end $$;
create or replace function public.prisma_order_status_logout(session_key text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin delete from public.prisma_order_status_sessions where session_hash=encode(sha256(convert_to(coalesce(session_key,''),'UTF8')),'hex');return jsonb_build_object('ok',true);end $$;
revoke all on function public.prisma_status_password_matches(text,text),public.prisma_order_status_login(text,text,text),public.prisma_order_status(text,text,text),public.prisma_order_status_logout(text) from public,anon,authenticated;
grant execute on function public.prisma_order_status_login(text,text,text),public.prisma_order_status(text,text,text),public.prisma_order_status_logout(text) to anon,authenticated;
notify pgrst,'reload schema';
commit;

-- Profile and shared page time settings; keep last after authenticated status wrappers.
-- Ejecutar después de las migraciones actuales de perfil, cuentas y consulta mensual.
begin;
create table if not exists public.prisma_site_time_settings(id integer primary key check(id=1),time_zone text not null default 'America/Mexico_City',time_format text not null default '24',updated_at timestamptz not null default now());
alter table public.prisma_site_time_settings enable row level security;
revoke all on public.prisma_site_time_settings from public,anon,authenticated;
insert into public.prisma_site_time_settings(id) values(1) on conflict do nothing;
create or replace function public.prisma_public_time_settings() returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select jsonb_build_object('timezoneMode','custom','timeZone',time_zone,'timeFormat',time_format) from public.prisma_site_time_settings where id=1$$;
create or replace function public.prisma_publish_profile_time() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare zone text:=new.preferences->>'timeZone';clock_format text:=new.preferences->>'timeFormat';
begin
 if zone is null then return new;end if;
 if not exists(select 1 from pg_timezone_names where name=zone) or coalesce(clock_format,'24') not in ('12','24') then raise exception 'Zona horaria o formato no válido.';end if;
 if exists(select 1 from public.prisma_admins where user_id=new.user_id) then update public.prisma_site_time_settings set time_zone=zone,time_format=coalesce(clock_format,'24'),updated_at=now() where id=1;end if;
 return new;
end $$;
drop trigger if exists prisma_publish_profile_time on public.prisma_user_preferences;
create trigger prisma_publish_profile_time after insert or update on public.prisma_user_preferences for each row execute function public.prisma_publish_profile_time();
update public.prisma_site_time_settings set time_zone=p.zone,time_format=p.format from (select u.preferences->>'timeZone' as zone,case when u.preferences->>'timeFormat'='12' then '12' else '24' end as format from public.prisma_user_preferences u join public.prisma_admins a on a.user_id=u.user_id where exists(select 1 from pg_timezone_names where name=u.preferences->>'timeZone') order by u.updated_at desc limit 1)p where id=1;
-- Today's date follows the caller's chosen zone, or the shared site clock for external pages.
create or replace function public.prisma_today() returns date language plpgsql stable security definer set search_path=public,pg_temp as $$
declare zone text;headers jsonb;preferences jsonb;
begin
 headers:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;zone:=substring(headers->>'x-client-info' from 'time-zone=([^; ]+)');
 if zone is null or not exists(select 1 from pg_timezone_names where name=zone) then select p.preferences into preferences from public.prisma_user_preferences p where p.user_id=auth.uid();zone:=preferences->>'timeZone';end if;
 if zone is null or not exists(select 1 from pg_timezone_names where name=zone) then select time_zone into zone from public.prisma_site_time_settings where id=1;end if;
 return timezone(coalesce(zone,'America/Mexico_City'),now())::date;
end $$;
do $$begin
 if to_regprocedure('public.prisma_order_portal_time_internal(text,jsonb)') is null then alter function public.prisma_order_portal(text,jsonb) rename to prisma_order_portal_time_internal;end if;
 if to_regprocedure('public.prisma_order_status_time_internal(text,text,text)') is null then alter function public.prisma_order_status(text,text,text) rename to prisma_order_status_time_internal;end if;
end $$;
revoke all on function public.prisma_public_time_settings(),public.prisma_publish_profile_time(),public.prisma_order_portal_time_internal(text,jsonb),public.prisma_order_status_time_internal(text,text,text) from public,anon,authenticated;
create or replace function public.prisma_order_portal(access_key text,payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin return public.prisma_order_portal_time_internal(access_key,payload)||jsonb_build_object('time_settings',public.prisma_public_time_settings());end $$;
create or replace function public.prisma_order_status(access_key text,target_month text,session_key text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin return public.prisma_order_status_time_internal(access_key,target_month,session_key)||jsonb_build_object('time_settings',public.prisma_public_time_settings());end $$;
revoke all on function public.prisma_order_portal(text,jsonb),public.prisma_order_status(text,text,text) from public,anon,authenticated;
grant execute on function public.prisma_order_portal(text,jsonb),public.prisma_order_status(text,text,text) to anon,authenticated;
notify pgrst,'reload schema';
commit;

-- Incident NP validation and safe timer updates.
-- Ejecutar completo después de accounts-and-sessions.sql. Conserva fotos, tiempos y folios.
begin;
create or replace function public.prisma_incident_np_valid(oid bigint,np_value text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select coalesce(btrim(np_value),'')='' or exists(select 1 from public.prisma_orders where id=oid and btrim(np)=btrim(np_value)) or exists(select 1 from public.prisma_items where order_id=oid and btrim(np)=btrim(np_value));
$$;
create or replace function public.prisma_start_incident_internal(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare b jsonb:=payload;old public.prisma_incidents%rowtype;o public.prisma_orders%rowtype;n integer;record_id bigint;start_time timestamptz:=clock_timestamp();np_value text;key text;
begin
 perform public.prisma_require_permission('incidents');perform pg_advisory_xact_lock(104202611);
 key:=nullif(b->>'request_key','');
 if key is not null then select * into old from public.prisma_incidents where request_key=key;if found then
  if old.order_id is distinct from (b->>'order_id')::bigint or not old.timer_mode then raise exception 'La captura ya está vinculada a otro registro.';end if;
  return jsonb_build_object('ok',true,'id',old.id,'folio','INC-'||lpad(old.incident_number::text,greatest(4,length(old.incident_number::text)),'0'),'started_at',old.started_at);
 end if;end if;
 select * into o from public.prisma_orders where id=(b->>'order_id')::bigint;if not found then raise exception 'Selecciona una orden registrada.';end if;
 select coalesce(max(incident_number),10)+1 into n from public.prisma_incidents;
 select case when count(distinct np)=1 then min(np) else '' end into np_value from (select nullif(btrim(o.np),'') as np union select nullif(btrim(i.np),'') from public.prisma_items i where i.order_id=o.id)x where np is not null;
 if nullif(btrim(b->>'np'),'') is not null then np_value:=btrim(b->>'np');end if;
 if not public.prisma_incident_np_valid(o.id,np_value) then raise exception 'El NP no pertenece a esa orden.';end if;
 insert into public.prisma_incidents(incident_number,date,order_id,order_ref,np,machine,description,responsible,impact,status,request_key,timer_mode,started_at) values(n,public.prisma_today(),o.id,o.folio,coalesce(np_value,''),'','Registro en curso','','','Abierta',key,true,start_time) returning id into record_id;
 return jsonb_build_object('ok',true,'id',record_id,'folio','INC-'||lpad(n::text,greatest(4,length(n::text)),'0'),'started_at',start_time);
end $$;
create or replace function public.prisma_update_timed_incident(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare b jsonb:=payload;r public.prisma_incidents%rowtype;finish boolean;before_value text;after_value text;ending timestamptz;np_value text;machine_value text;responsible_value text;impact_value text;
begin
 perform public.prisma_require_permission('incidents');perform pg_advisory_xact_lock(104202611);
 select * into r from public.prisma_incidents where id=(b->>'id')::bigint;if not found or not r.timer_mode then raise exception 'Cronómetro no encontrado.';end if;
 if r.order_id is distinct from (b->>'order_id')::bigint then raise exception 'No se puede cambiar la orden del cronómetro.';end if;
 finish:=coalesce((b->>'finish')::boolean,false) or r.ended_at is not null;
 before_value:=case when b?'before_photo' then b->>'before_photo' else r.before_photo end;after_value:=case when b?'after_photo' then b->>'after_photo' else r.after_photo end;
 perform public.prisma_check_incident_photo(before_value);perform public.prisma_check_incident_photo(after_value);
 if finish and (coalesce(before_value,'')='' or coalesce(after_value,'')='') then raise exception 'Agrega la foto del defecto y la foto final.';end if;
 machine_value:=coalesce(b->>'machine',r.machine);responsible_value:=coalesce(b->>'responsible',r.responsible);impact_value:=coalesce(b->>'impact',r.impact);np_value:=btrim(coalesce(b->>'np',r.np));
 if machine_value<>'' and machine_value not in ('Mark Andy','Comco 1','Comco 2','Maquina China') then raise exception 'Máquina no válida.';end if;
 if responsible_value<>'' and responsible_value not in ('Diseño','Producción','Preprensa','Proveedor','Mantenimiento','Compartida') then raise exception 'Responsable no válido.';end if;
 if impact_value<>'' and impact_value not in ('Merma','Paro','Retrabajo','Calidad','Entrega','Otro') then raise exception 'Impacto no válido.';end if;
 if not public.prisma_incident_np_valid(r.order_id,np_value) then raise exception 'NP no válido.';end if;
 ending:=coalesce(r.ended_at,case when finish then clock_timestamp() else null end);
 update public.prisma_incidents set np=np_value,machine=machine_value,responsible=responsible_value,impact=impact_value,description=coalesce(nullif(b->>'description',''),r.description),action=coalesce(nullif(b->>'action',''),case when finish then 'Corrección documentada en fotografía final.' else r.action end),status=case when finish then 'Cerrada' else 'Abierta' end,prepared_by=coalesce(b->>'prepared_by',r.prepared_by),color_observed=coalesce(b->>'color_observed',r.color_observed),test_result=coalesce(b->>'test_result',r.test_result),validation_notes=coalesce(b->>'validation_notes',r.validation_notes),before_photo=before_value,after_photo=after_value,ended_at=ending where id=r.id;
 return jsonb_build_object('ok',true,'id',r.id,'folio','INC-'||lpad(r.incident_number::text,greatest(4,length(r.incident_number::text)),'0'),'started_at',r.started_at,'ended_at',ending);
end $$;
create or replace function public.prisma_save_incident_internal(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
<<inc>>
declare b jsonb:=payload;d date;oid bigint;ref text;record_id bigint;folio_number integer;np_value text;key text;
begin
 perform public.prisma_require_permission('incidents');perform pg_advisory_xact_lock(104202611);
 key:=nullif(b->>'request_key','');record_id:=nullif(b->>'id','')::bigint;
 if record_id is not null and exists(select 1 from public.prisma_incidents where id=record_id and timer_mode) then return public.prisma_update_timed_incident(b);end if;
 if key is not null and record_id is null then
  select id,incident_number into record_id,folio_number from public.prisma_incidents where request_key=key;
  if found then return jsonb_build_object('ok',true,'id',record_id,'folio','INC-'||lpad(folio_number::text,greatest(4,length(folio_number::text)),'0'));end if;
 end if;
 if coalesce(b->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha no válida.';end if;
 d:=(b->>'date')::date;if d>public.prisma_today() then raise exception 'No se permiten incidencias con fecha futura.';end if;
 oid:=nullif(b->>'order_id','')::bigint;select folio into ref from public.prisma_orders where id=oid;if not found then raise exception 'Selecciona una orden de producción registrada.';end if;
 np_value:=btrim(coalesce(b->>'np',''));if not public.prisma_incident_np_valid(oid,np_value) then raise exception 'El NP no pertenece a esa orden.';end if;
 if b->>'machine' is null or b->>'machine' not in ('Mark Andy','Comco 1','Comco 2','Maquina China') then raise exception 'Máquina no válida.';end if;
 if b->>'responsible' is null or b->>'responsible' not in ('Diseño','Producción','Preprensa','Proveedor','Mantenimiento','Compartida') then raise exception 'Responsable no válido.';end if;
 if b->>'impact' is null or b->>'impact' not in ('Merma','Paro','Retrabajo','Calidad','Entrega','Otro') then raise exception 'Impacto no válido.';end if;
 if b->>'status' is null or b->>'status' not in ('Abierta','En seguimiento','Cerrada') then raise exception 'Estatus no válido.';end if;
 if coalesce(btrim(b->>'description'),'')='' then raise exception 'Describe la incidencia.';end if;
 if b->>'status'='Cerrada' and coalesce(btrim(b->>'action'),'')='' then raise exception 'Captura la acción realizada antes de cerrar la incidencia.';end if;
 if record_id is null then
  select coalesce(max(incident_number),10)+1 into folio_number from public.prisma_incidents;
  insert into public.prisma_incidents(incident_number,date,order_id,order_ref,np,machine,description,responsible,action,impact,status,prepared_by,color_observed,test_result,validation_notes,request_key) values(folio_number,d,oid,ref,np_value,b->>'machine',b->>'description',b->>'responsible',coalesce(b->>'action',''),b->>'impact',b->>'status',coalesce(b->>'prepared_by',''),coalesce(b->>'color_observed',''),coalesce(b->>'test_result',''),coalesce(b->>'validation_notes',''),key) returning id into record_id;
 else
  update public.prisma_incidents set date=d,order_id=oid,order_ref=ref,np=np_value,machine=b->>'machine',description=b->>'description',responsible=b->>'responsible',action=coalesce(b->>'action',''),impact=b->>'impact',status=b->>'status',prepared_by=coalesce(b->>'prepared_by',''),color_observed=coalesce(b->>'color_observed',''),test_result=coalesce(b->>'test_result',''),validation_notes=coalesce(b->>'validation_notes','') where id=record_id returning incident_number into folio_number;
  if not found then raise exception 'Incidencia no encontrada.';end if;
 end if;
 return jsonb_build_object('ok',true,'id',record_id,'folio','INC-'||lpad(folio_number::text,greatest(4,length(folio_number::text)),'0'));
end $$;
create or replace function public.prisma_start_incident(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin perform public.prisma_require_permission('incidents');return public.prisma_start_incident_internal(payload);end $$;
create or replace function public.prisma_save_incident(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin perform public.prisma_require_permission('incidents');return public.prisma_save_incident_internal(payload);end $$;
revoke all on function public.prisma_incident_np_valid(bigint,text),public.prisma_start_incident_internal(jsonb),public.prisma_save_incident_internal(jsonb),public.prisma_update_timed_incident(jsonb),public.prisma_start_incident(jsonb),public.prisma_save_incident(jsonb) from public,anon,authenticated;
grant execute on function public.prisma_start_incident(jsonb),public.prisma_save_incident(jsonb) to authenticated;
notify pgrst,'reload schema';
commit;

-- Profile archive and operator production forms generated after preparation.
-- Ejecutar después de cuentas/permisos y preparación. No cambia inventario ni consumos.
begin;
create table if not exists public.prisma_press_sheets(id bigint generated by default as identity primary key,order_id bigint not null unique references public.prisma_orders(id),profile_id uuid not null references auth.users(id),access_key text not null unique,source jsonb not null,fields jsonb not null default '{}',version integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.prisma_press_sheets enable row level security;
revoke all on public.prisma_press_sheets from public,anon,authenticated;
create or replace function public.prisma_press_sheets(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare o public.prisma_orders%rowtype;row_value public.prisma_press_sheets%rowtype;prefs jsonb;source_value jsonb;colors jsonb;zone text;headers jsonb;
begin
 perform public.prisma_authorize();if not public.prisma_has_permission(auth.uid(),'preparation') and not public.prisma_has_permission(auth.uid(),'production') then raise exception 'No tienes permiso para órdenes de prensista.';end if;
 if payload->>'operation'='list' then return jsonb_build_object('sheets',coalesce((select jsonb_agg((to_jsonb(s)-'fields'-'source')||jsonb_build_object('source',s.source-'reportLogo'-'colors') order by s.id desc) from public.prisma_press_sheets s where s.profile_id=auth.uid()),'[]'::jsonb));end if;
 if payload->>'operation' is distinct from 'generate' then raise exception 'Acción no válida.';end if;
 perform pg_advisory_xact_lock(104202611);select * into o from public.prisma_orders where id=(payload->>'order_id')::bigint;
 if not found or o.ended_at is null or o.status='cancelled' then raise exception 'Primero finaliza la preparación de la orden.';end if;
 select * into row_value from public.prisma_press_sheets where order_id=o.id;
 if found then if row_value.profile_id<>auth.uid() then raise exception 'La hoja ya está guardada en el perfil de quien finalizó la preparación.';end if;return to_jsonb(row_value);end if;
 select preferences into prefs from public.prisma_user_preferences where user_id=auth.uid();prefs:=coalesce(prefs,'{}'::jsonb);
 headers:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;zone:=substring(headers->>'x-client-info' from 'time-zone=([^; ]+)');if zone is null or not exists(select 1 from pg_timezone_names where name=zone) then zone:=coalesce(prefs->>'timeZone','America/Mexico_City');end if;
 select coalesce(jsonb_agg(jsonb_build_object('slot',i.value->'slot','name',case when coalesce(i.value->>'pantone','')<>'' then 'Pantone '||(i.value->>'pantone') else coalesce(p.name,'') end,'code',coalesce(p.code,''),'family',coalesce(i.value->>'ink_family',o.specifications->>'tipo_tinta','')) order by (i.value->>'slot')::integer),'[]'::jsonb) into colors from jsonb_array_elements(o.ink_selections) i left join public.prisma_products p on p.id=nullif(i.value->>'product_id','')::bigint;
 source_value:=jsonb_build_object('folio',o.folio,'np',coalesce(nullif(o.np,''),(select string_agg(distinct np,', ') from public.prisma_items where order_id=o.id and np<>''),''),'product',coalesce(nullif(o.product,''),o.client,''),'client',o.client,'pressman',o.pressman,'machine',o.machine,'date',o.date,'required_date',o.scheduled_date,'planned_meters',o.planned_meters,'pieces',o.pieces,'started_at',o.started_at,'ended_at',o.ended_at,'suaje',coalesce(o.specifications->>'suaje',''),'pleca',coalesce(o.specifications->>'pleca',''),'colors',colors,'prepared_by',coalesce(prefs->>'reportName',''),'reportLogo',prefs->'reportLogo','time_settings',jsonb_build_object('timezoneMode','custom','timeZone',zone,'timeFormat',coalesce(prefs->>'timeFormat','24')));
 insert into public.prisma_press_sheets(order_id,profile_id,access_key,source) values(o.id,auth.uid(),'ps_'||encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex'),source_value) returning * into row_value;return to_jsonb(row_value);
end $$;
create or replace function public.prisma_press_sheet(access_key text,payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare row_value public.prisma_press_sheets%rowtype;cancelled boolean;key_name text;value jsonb;allowed text[]:=array['category','scrap_target','width_in','height_in','width_mm','height_mm','priority','lamination','material_surface','material_adhesive','material_liner','material_code','material_delivered','material_pending','bobina_1_reel','bobina_1_eur','bobina_1_des','bobina_1_lot','bobina_1_meters','bobina_2_reel','bobina_2_eur','bobina_2_des','bobina_2_lot','bobina_2_meters','bobina_3_reel','bobina_3_eur','bobina_3_des','bobina_3_lot','bobina_3_meters','bobina_4_reel','bobina_4_eur','bobina_4_des','bobina_4_lot','bobina_4_meters','bobina_5_reel','bobina_5_eur','bobina_5_des','bobina_5_lot','bobina_5_meters','die_quantity','die_identification','die_state_out','die_date_out','die_state_return','die_date_return','crease_quantity','crease_identification','crease_state_out','crease_date_out','crease_state_return','crease_date_return','setup_expected','setup_actual','production_expected','production_actual','meters_actual','production_speed','pressman','prepress_signature','press_signature','observations','labels_per_roll','core_diameter','outer_diameter','core_material','turns_machine_1','turns_machine_2','turns_machine_3','rewind_expected','rewind_actual','rewind_date','labels_min','labels_max','labels_finished','thousands_ship','thousands_received','rewind_signature','dispatch_signature','box_size','boxes','bag','rolls_per_box','packing_signature','registration_min','registration_max','waste_percent','production_percent','operations_signature','production_signature','quality_signature'];
begin
 if access_key is null or access_key !~ '^ps_[a-f0-9]{64}$' then raise exception 'Enlace no autorizado.';end if;
 select * into row_value from public.prisma_press_sheets s where s.access_key=prisma_press_sheet.access_key for update;if not found then raise exception 'Enlace no autorizado.';end if;
 select status='cancelled' into cancelled from public.prisma_orders where id=row_value.order_id;
 if payload->>'operation'='save' then
  if cancelled then raise exception 'La orden fue cancelada. Solo se puede consultar.';end if;
  if (payload->>'version')::integer is distinct from row_value.version then raise exception 'Otra persona actualizó el formato. Recarga antes de guardar.';end if;
  if jsonb_typeof(payload->'fields') is distinct from 'object' or octet_length((payload->'fields')::text)>50000 then raise exception 'Datos del formato no válidos.';end if;
  for key_name,value in select * from jsonb_each(payload->'fields') loop if not key_name=any(allowed) or jsonb_typeof(value)<>'string' or length(value#>>'{}')>(case when key_name='observations' then 2000 else 200 end) then raise exception 'Campo no permitido o demasiado largo.';end if;end loop;
  update public.prisma_press_sheets set fields=payload->'fields',version=version+1,updated_at=now() where id=row_value.id returning * into row_value;
 elsif payload->>'operation' is distinct from 'get' then raise exception 'Acción no válida.';end if;
 return (to_jsonb(row_value)-'profile_id'-'access_key'-'order_id')||jsonb_build_object('cancelled',cancelled);
end $$;
do $$begin if to_regprocedure('public.prisma_order_clock_press_internal(jsonb)') is null then alter function public.prisma_order_clock(jsonb) rename to prisma_order_clock_press_internal;end if;end $$;
revoke all on function public.prisma_order_clock_press_internal(jsonb) from public,anon,authenticated;
create or replace function public.prisma_order_clock(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare result jsonb;sheet jsonb;
begin result:=public.prisma_order_clock_press_internal(payload);if payload->>'operation'='finish' then sheet:=public.prisma_press_sheets(jsonb_build_object('operation','generate','order_id',payload->'id'));result:=result||jsonb_build_object('press_sheet',sheet);end if;return result;end $$;
revoke all on function public.prisma_press_sheets(jsonb),public.prisma_press_sheet(text,jsonb),public.prisma_order_clock(jsonb) from public,anon,authenticated;
grant execute on function public.prisma_press_sheets(jsonb),public.prisma_order_clock(jsonb) to authenticated;
grant execute on function public.prisma_press_sheet(text,jsonb) to anon,authenticated;
notify pgrst,'reload schema';
commit;

-- Flujo por bobinas. Aplicar después de press-sheets.sql en instalaciones anteriores.
begin;
create table if not exists public.prisma_press_queues(profile_id uuid primary key references auth.users(id),production_key text not null unique default ('pq_'||encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex')),rewind_key text not null unique default ('rq_'||encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex')));
alter table public.prisma_press_queues enable row level security;
revoke all on public.prisma_press_queues from public,anon,authenticated;
alter table public.prisma_press_sheets add column if not exists rewind_key text;
alter table public.prisma_press_sheets add column if not exists bobinas jsonb not null default '[]';
create unique index if not exists prisma_press_rewind_key on public.prisma_press_sheets(rewind_key);
create or replace function public.prisma_planned_bobinas(meters text) returns jsonb language plpgsql set search_path=public,pg_temp as $$
declare total numeric;n integer;begin total:=nullif(meters,'')::numeric;if total is null or total<=0 then return '[]';end if;if total::text in ('NaN','Infinity','-Infinity') or total>15000000 then raise exception 'Metraje fuera de rango.';end if;n:=ceil(total/1500);return (select jsonb_agg(jsonb_build_object('number',i,'planned_meters',least(1500,total-(i-1)*1500),'produced_at',null,'rewound_at',null) order by i) from generate_series(1,n) i);end $$;
revoke all on function public.prisma_planned_bobinas(text) from public,anon,authenticated;
update public.prisma_press_sheets set rewind_key='rw_'||encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex'),bobinas=public.prisma_planned_bobinas(source->>'planned_meters') where rewind_key is null;
create or replace function public.prisma_press_sheets(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare o public.prisma_orders%rowtype;row_value public.prisma_press_sheets%rowtype;prefs jsonb;source_value jsonb;colors jsonb;zone text;headers jsonb;pending record;
begin
 perform public.prisma_authorize();if not public.prisma_has_permission(auth.uid(),'preparation') and not public.prisma_has_permission(auth.uid(),'production') then raise exception 'No tienes permiso para órdenes de prensista.';end if;
 if payload->>'operation'='list' then
  insert into public.prisma_press_queues(profile_id) values(auth.uid()) on conflict do nothing;
  if exists(select 1 from public.prisma_admins where user_id=auth.uid()) then
   perform pg_advisory_xact_lock(104202611);
   for pending in select legacy.id from public.prisma_orders legacy where legacy.status<>'cancelled' and (legacy.ended_at is not null or legacy.status='confirmed') and not exists(select 1 from public.prisma_press_sheets s where s.order_id=legacy.id) loop
    perform public.prisma_press_sheets(jsonb_build_object('operation','generate','order_id',pending.id));
   end loop;
  end if;
 return jsonb_build_object('workflow_version',2,'links',(select jsonb_build_object('production_key',production_key,'rewind_key',rewind_key) from public.prisma_press_queues where profile_id=auth.uid()),'sheets',coalesce((select jsonb_agg((to_jsonb(s)-'fields'-'source')||jsonb_build_object('source',s.source-'reportLogo'-'colors') order by s.id desc) from public.prisma_press_sheets s where s.profile_id=auth.uid()),'[]'::jsonb));end if;
 if payload->>'operation' is distinct from 'generate' then raise exception 'Acción no válida.';end if;
 perform pg_advisory_xact_lock(104202611);select * into o from public.prisma_orders where id=(payload->>'order_id')::bigint;
 if not found or (o.ended_at is null and o.status<>'confirmed') or o.status='cancelled' then raise exception 'Primero finaliza la preparación de la orden.';end if;
 select * into row_value from public.prisma_press_sheets where order_id=o.id;
 if found then if row_value.profile_id<>auth.uid() then raise exception 'La hoja ya está guardada en el perfil de quien finalizó la preparación.';end if;return to_jsonb(row_value);end if;
 select preferences into prefs from public.prisma_user_preferences where user_id=auth.uid();prefs:=coalesce(prefs,'{}'::jsonb);
 headers:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;zone:=substring(headers->>'x-client-info' from 'time-zone=([^; ]+)');if zone is null or not exists(select 1 from pg_timezone_names where name=zone) then zone:=coalesce(prefs->>'timeZone','America/Mexico_City');end if;
 select coalesce(jsonb_agg(jsonb_build_object('slot',i.value->'slot','name',case when coalesce(i.value->>'pantone','')<>'' then 'Pantone '||(i.value->>'pantone') else coalesce(p.name,'') end,'code',coalesce(p.code,''),'family',coalesce(i.value->>'ink_family',o.specifications->>'tipo_tinta','')) order by (i.value->>'slot')::integer),'[]'::jsonb) into colors from jsonb_array_elements(o.ink_selections) i left join public.prisma_products p on p.id=nullif(i.value->>'product_id','')::bigint;
 if colors='[]'::jsonb then
  if coalesce(o.specifications->>'colores','')<>'' then colors:=jsonb_build_array(jsonb_build_object('slot',1,'name',o.specifications->>'colores','code','','family',coalesce(o.specifications->>'tipo_tinta','')));
  else select coalesce(jsonb_agg(jsonb_build_object('slot',ink.slot,'name',ink.name,'code',ink.code,'family',ink.kind)),'[]'::jsonb) into colors from (select row_number() over(order by p.code) as slot,p.name,p.code,p.kind from public.prisma_items item join public.prisma_lots l on l.id=item.lot_id join public.prisma_products p on p.id=l.product_id where item.order_id=o.id group by p.name,p.code,p.kind) ink;end if;
 end if;
 source_value:=jsonb_build_object('folio',o.folio,'np',coalesce(nullif(o.np,''),(select string_agg(distinct np,', ') from public.prisma_items where order_id=o.id and np<>''),''),'product',coalesce(nullif(o.product,''),o.client,''),'client',o.client,'pressman',o.pressman,'machine',o.machine,'date',o.date,'required_date',o.scheduled_date,'planned_meters',coalesce(o.planned_meters,(select max(meters) from public.prisma_items where order_id=o.id)),'pieces',o.pieces,'started_at',o.started_at,'ended_at',o.ended_at,'suaje',coalesce(o.specifications->>'suaje',''),'pleca',coalesce(o.specifications->>'pleca',''),'colors',colors,'prepared_by',coalesce(prefs->>'reportName',''),'reportLogo',prefs->'reportLogo','time_settings',jsonb_build_object('timezoneMode','custom','timeZone',zone,'timeFormat',coalesce(prefs->>'timeFormat','24')));
 insert into public.prisma_press_sheets(order_id,profile_id,access_key,source) values(o.id,auth.uid(),'ps_'||encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex'),source_value) returning * into row_value;update public.prisma_press_sheets set rewind_key='rw_'||encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex'),bobinas=public.prisma_planned_bobinas(source->>'planned_meters') where id=row_value.id returning * into row_value;return to_jsonb(row_value);
end $$;

create or replace function public.prisma_press_sheet(access_key text,payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare row_value public.prisma_press_sheets%rowtype;cancelled boolean;stage text;key_name text;value jsonb;allowed text[];bobina jsonb;idx integer;done_field text;filtered jsonb;
begin
 if access_key is null or access_key !~ '^(ps|rw)_[a-f0-9]{64}$' then raise exception 'Enlace no autorizado.';end if;
 select * into row_value from public.prisma_press_sheets s where s.access_key=prisma_press_sheet.access_key or s.rewind_key=prisma_press_sheet.access_key for update;if not found then raise exception 'Enlace no autorizado.';end if;
 stage:=case when row_value.access_key=access_key then 'production' else 'rewind' end;
 allowed:=case when stage='production' then array['category','scrap_target','width_in','height_in','width_mm','height_mm','priority','lamination','material_surface','material_adhesive','material_liner','material_code','material_delivered','material_pending','bobina_1_reel','bobina_1_eur','bobina_1_des','bobina_1_lot','bobina_1_meters','bobina_2_reel','bobina_2_eur','bobina_2_des','bobina_2_lot','bobina_2_meters','bobina_3_reel','bobina_3_eur','bobina_3_des','bobina_3_lot','bobina_3_meters','bobina_4_reel','bobina_4_eur','bobina_4_des','bobina_4_lot','bobina_4_meters','bobina_5_reel','bobina_5_eur','bobina_5_des','bobina_5_lot','bobina_5_meters','die_quantity','die_identification','die_state_out','die_date_out','die_state_return','die_date_return','crease_quantity','crease_identification','crease_state_out','crease_date_out','crease_state_return','crease_date_return','setup_expected','setup_actual','production_expected','production_actual','meters_actual','production_speed','pressman','prepress_signature','press_signature','observations'] else array['labels_per_roll','core_diameter','outer_diameter','core_material','turns_machine_1','turns_machine_2','turns_machine_3','rewind_expected','rewind_actual','rewind_date','labels_min','labels_max','labels_finished','thousands_ship','thousands_received','rewind_signature','dispatch_signature','box_size','boxes','bag','rolls_per_box','packing_signature','registration_min','registration_max','waste_percent','production_percent','operations_signature','production_signature','quality_signature'] end;
 select status='cancelled' into cancelled from public.prisma_orders where id=row_value.order_id;
 if payload->>'operation' in ('save','complete_bobina') then
  if cancelled then raise exception 'La orden fue cancelada. Solo se puede consultar.';end if;
  if (payload->>'version')::integer is distinct from row_value.version then raise exception 'Otra persona actualizó el formato. Recarga antes de guardar.';end if;
  if stage='rewind' and not exists(select 1 from jsonb_array_elements(row_value.bobinas) b where b->>'produced_at' is not null) then raise exception 'Rebobinado estará disponible al terminar la primera bobina.';end if;
  if payload->>'operation'='save' then
   if jsonb_typeof(payload->'fields') is distinct from 'object' or octet_length((payload->'fields')::text)>50000 then raise exception 'Datos del formato no válidos.';end if;
   for key_name,value in select * from jsonb_each(payload->'fields') loop if not key_name=any(allowed) or jsonb_typeof(value)<>'string' or length(value#>>'{}')>(case when key_name='observations' then 2000 else 200 end) then raise exception 'Campo no permitido en esta etapa o demasiado largo.';end if;end loop;
   update public.prisma_press_sheets set fields=fields||(payload->'fields'),version=version+1,updated_at=now() where id=row_value.id returning * into row_value;
  else
   if coalesce(payload->>'number','') !~ '^[1-9][0-9]{0,4}$' then raise exception 'Bobina no válida.';end if;
   idx:=(payload->>'number')::integer-1;bobina:=row_value.bobinas->idx;if bobina is null then raise exception 'Bobina no válida.';end if;
   done_field:=case when stage='production' then 'produced_at' else 'rewound_at' end;
   if bobina->>done_field is null then
    if stage='production' and idx>0 and row_value.bobinas->(idx-1)->>'produced_at' is null then raise exception 'Termina primero la bobina anterior.';end if;
    if stage='rewind' and bobina->>'produced_at' is null then raise exception 'Primero termina la producción de esta bobina.';end if;
    update public.prisma_press_sheets set bobinas=jsonb_set(bobinas,array[idx::text,done_field],to_jsonb(now())),version=version+1,updated_at=now() where id=row_value.id returning * into row_value;
   end if;
  end if;
 elsif payload->>'operation' is distinct from 'get' then raise exception 'Acción no válida.';end if;
 select coalesce(jsonb_object_agg(entry.key,entry.value),'{}') into filtered from jsonb_each(row_value.fields) entry where entry.key=any(allowed);
 return (to_jsonb(row_value)-'profile_id'-'access_key'-'rewind_key'-'order_id'-'fields')||jsonb_build_object('fields',filtered,'cancelled',cancelled,'stage',stage,'rewind_ready',exists(select 1 from jsonb_array_elements(row_value.bobinas) b where b->>'produced_at' is not null));
end $$;
revoke all on function public.prisma_press_sheets(jsonb),public.prisma_press_sheet(text,jsonb) from public,anon,authenticated;
grant execute on function public.prisma_press_sheets(jsonb) to authenticated;
grant execute on function public.prisma_press_sheet(text,jsonb) to anon,authenticated;
create or replace function public.prisma_press_queue(access_key text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare q public.prisma_press_queues%rowtype;stage text;result jsonb;
begin
 if access_key is null or access_key !~ '^(pq|rq)_[a-f0-9]{64}$' then raise exception 'Enlace no autorizado.';end if;
 select * into q from public.prisma_press_queues queue where queue.production_key=prisma_press_queue.access_key or queue.rewind_key=prisma_press_queue.access_key;if not found then raise exception 'Enlace no autorizado.';end if;
 stage:=case when q.production_key=access_key then 'production' else 'rewind' end;
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'access_key',case when stage='production' then s.access_key else s.rewind_key end,'bobinas',s.bobinas,'source',jsonb_build_object('folio',s.source->'folio','np',s.source->'np','product',s.source->'product','machine',s.source->'machine','date',s.source->'date','planned_meters',s.source->'planned_meters')) order by s.id),'[]'::jsonb) into result from public.prisma_press_sheets s join public.prisma_orders o on o.id=s.order_id where s.profile_id=q.profile_id and o.status<>'cancelled' and (stage='production' or exists(select 1 from jsonb_array_elements(s.bobinas) b where b->>'produced_at' is not null));
 return jsonb_build_object('stage',stage,'sheets',result);
end $$;
revoke all on function public.prisma_press_queue(text) from public,anon,authenticated;
